from lib import *
S = SS('h4')
steps = [
    step("服务端流先发 2 条消息再出错:线上帧是 HEADERS(:status: 200; content-type: application/grpc)、DATA、DATA,最后一个带 END_STREAM 的 HEADERS 里是 grpc-status: 13; grpc-message: …(Internal)。客户端先收到 2 条消息,然后 Recv 返回 code=Internal message=“第三条出错了”。HTTP 状态 200 在第一个 HEADERS 里就已经发出去了,不能再改;而流在发送消息的过程中才可能出错,所以错误只能放在消息之后的 trailers 里。这就是 grpc-status 放在 trailers 的原因。", t=tl(S(1)), done=lidx(S(1), '客户端:收到 2 条消息'), mark=lidx(S(1), 'S→C HEADERS  标志 END_STREAM'), b=bars([['出错前已收到的消息', 2, '2'], ['grpc-status 数字', 13, '13']], 14, done=[0], mark=[1]), kv=KV([['HTTP 状态', '第一个 HEADERS 就是 200,之后不可改'], ['错误', '放在最后的 trailers:grpc-status: 13'], ['客户端', '先收到 2 条消息,再得到 Internal']], ['错误'])),
    step("一条消息都没发就失败时,响应只有一个 HEADERS 帧:同时带 :status: 200、content-type: application/grpc、grpc-status: 7、grpc-message: …,并且带 END_STREAM(trailers-only)。客户端得到 code=PermissionDenied、收到 0 条消息。对照正常返回 3 条消息的流:HEADERS、3 个 DATA、带 END_STREAM 的 HEADERS(grpc-status: 0; grpc-message: 空)共 5 个帧。失败得越早,线上的帧越少。", t=tl(S(2)), done=lidx(S(2), '客户端:收到 0 条消息'), mark=lidx(S(2), '对照:正常返回'), b=bars([['trailers-only 失败的帧数', 1, '1'], ['正常 3 条消息的帧数', 5, '5']], 6, done=[0], mark=[1]), kv=KV([['失败且无消息', '1 个 HEADERS(含 grpc-status,带 END_STREAM)'], ['正常 3 条消息', 'HEADERS + 3×DATA + trailers = 5 帧'], ['客户端', 'PermissionDenied,0 条消息']], ['失败且无消息'])),
    step("grpc-message 要做百分号编码:服务端的 message 是 “参数错误:id=100%\\n第二行”(含中文、百分号、换行),线上是 grpc-message: %E5%8F%82%E6%95%B0%E9%94%99%E8%AF%AF:id=100%25%0A%E7%AC%AC%E4%BA%8C%E8%A1%8C,中文变成 UTF-8 字节的 %XX,百分号变成 %25,换行变成 %0A,冒号保持原样;客户端解码后与服务端原文完全相同。所以 message 里放什么字符都安全,代价是线上变长(这条 30 字节的 message,编码后的值有 76 个字符,约 2.5 倍;这两个数是我按上面的原文和线上字符串数出来的)。", t=tl(S(3)), done=lidx(S(3), '客户端解码后'), mark=lidx(S(3), '线上 grpc-message'), b=bars([['原文 message 字节(UTF-8)', 30, '30'], ['线上 grpc-message 字节', 76, '76']], 80, mark=[1], done=[0]), kv=KV([['中文', 'UTF-8 字节逐个变成 %XX'], ['% 与换行', '%25、%0A'], ['客户端', '自动解码,与原文相同']], ['中文'])),
    step("应用自己的 trailers:服务端 SetTrailer 三个键 x-served-by: node-7、x-cost-ms: 12、x-blob-bin(二进制值 00 01 fe ff),客户端用 grpc.Trailer 取到 [\"node-7\"]、[\"12\"] 和原样的二进制字节。线上的 trailers 帧是 grpc-status: 0; grpc-message: ; x-cost-ms: 12; x-blob-bin: AAH+/w; x-served-by: node-7——以 -bin 结尾的键,值在线上用不带填充的 base64(AAH+/w)传输。trailers 里可以放响应结束之后才知道的信息,比如处理耗时。", t=tl(S(4)), done=lidx(S(4), '线上 trailers 帧'), mark=lidx(S(4), '客户端 trailer x-blob-bin'), b=bars([['二进制值 字节', 4, '4'], ['线上 base64 字符数', 6, '6']], 7, done=[1], mark=[0]), kv=KV([['x-served-by / x-cost-ms', '文本值原样'], ['x-blob-bin', '二进制值,线上 base64 无填充(AAH+/w)'], ['取法', '客户端 grpc.Trailer(&md)']], ['x-blob-bin'])),
    step("流到一半连接断了(trailers 没来得及发):客户端先收到 1 条消息,然后 Recv 返回 code=Unavailable message=“error reading from server: EOF”。没有 trailers 就没有 grpc-status,客户端只能从连接错误推断出 Unavailable。已经收到的消息没有丢,但你不知道服务端是否处理完了——要不要重试取决于业务是否幂等(第 18 篇)。", t=tl(S(5)), done=lidx(S(5), '客户端先收到 1 条消息'), b=bars([['断开前收到的消息', 1, '1'], ['Unavailable 的 code 编号', 14, '14']], 15, done=[0, 1]), kv=KV([['现象', '收到 1 条消息后 Recv 报 Unavailable'], ['message', 'error reading from server: EOF'], ['含义', '服务端有没有处理完不知道']], ['含义'])),
    step("一个只回 HEADERS 加 DATA、不发 trailers 的服务器(比如不支持 trailers 的代理):客户端拿到合法的消息本体,但最终 resp 为空,code=Internal message=“server closed the stream without sending trailers”。gRPC 要求响应必须以 trailers 结尾;缺少它,客户端就认为调用不完整,即使消息本身读到了。这是 HTTP/1.1 代理或不支持 trailers 的网关会导致的典型错误。", t=tl(S(6)), done=lidx(S(6), '服务器回了合法的消息'), b=bars([['收到的响应消息', 0, '0(resp 为空)'], ['code Internal 编号', 13, '13']], 14, done=[1]), kv=KV([['服务器', '合法消息,但没有 grpc-status trailers'], ['客户端', 'Internal: server closed the stream without sending trailers'], ['常见原因', '不支持 trailers 的代理或网关']], ['客户端'])),
]
A = mkarth('h4', 4, 'gRPC,trailers,grpc-status,grpc-message,HTTP/2,百分号编码,Go,真实验证,动画演示',
    '为什么 grpc-status 放在 trailers:HTTP 状态 200 在第一个 HEADERS 就发出去了,流中途出错只能放在最后;一条消息都没发就失败是 trailers-only 的单个 HEADERS;grpc-message 做百分号编码;-bin 键用 base64;连接中途断了得到 Unavailable;缺少 trailers 得到 Internal。',
    '第 1 篇提到调用结果放在最后的 trailers 里。为什么非得这样?什么叫 trailers-only?message 里的中文怎么传?trailers 没来会怎样?这篇逐个抓包验证。',
    [('1 对 5', '一条消息都没发就失败(trailers-only)与正常返回 3 条消息的流,响应的帧数'), ('%E5%8F%82…', '中文 grpc-message 在线上的百分号编码,客户端自动解码还原'), ('Internal', '服务器缺少 trailers 时客户端的错误:server closed the stream without sending trailers')],
    [('为什么在末尾', '<p>响应的 HTTP 状态在第一个 HEADERS 里就确定了(永远是 200),而流式 RPC 要到发完消息才知道成败,所以成败写在最后的 trailers(带 END_STREAM 的 HEADERS)里。</p>'),
     ('trailers-only', '<p>失败得早、一条消息都没发时,服务端把 :status、content-type、grpc-status、grpc-message 合并成一个带 END_STREAM 的 HEADERS,没有 DATA。</p>'),
     ('message 的编码', '<p>grpc-message 的值做百分号编码,所以任意字符都能放;客户端自动解码。线上会变长,中文尤其明显。</p>'),
     ('应用 trailers', '<p>服务端可以在响应末尾带自己的 trailers(耗时、实例名等),二进制值用 -bin 结尾的键,线上是无填充的 base64。</p>'),
     ('trailers 没来', '<p>连接中途断开:客户端收到 Unavailable(error reading from server: EOF),已收的消息不丢,但不知道服务端有没有处理完。</p>'),
     ('不支持 trailers 的中间层', '<p>HTTP/1.1 代理等不转发 trailers 的组件会让客户端报 Internal: server closed the stream without sending trailers。这是 gRPC 要求路径上都是支持 trailers 的 HTTP/2 的原因。</p>')],
    steps,
    [ENV_H + '。第五节用抓包代理的 CutAll 在服务端发了一条消息之后掐断所有 TCP 连接;第六节的“不发 trailers 的服务器”是 h2c 的 net/http 服务,只写了 HEADERS 和一条合法的 gRPC 消息;所有结果是确定的',
     '没有验证:Java、C++ 客户端在缺少 trailers 时是否报同样的错;HTTP/1.1 网关的具体行为;trailers 的大小限制;grpc-message 的长度限制(头列表大小上限);“x-blob-bin” 以外的二进制元数据在 HEADERS 里的表现(第 7 篇)'],
    'trailers')
